// ── HELPERS ───────────────────────────────────────────────────────────────────
function sqlEsc(v) {
  if (v === null || v === undefined) return 'NULL';
  return `'${String(v).replace(/'/g, "''")}'`;
}

// ── MERGE ─────────────────────────────────────────────────────────────────────
// Deduplicate Source A by ticker (last occurrence wins — data is clean, all same)
const sourceAMap = new Map();
for (const e of SOURCE_A) {
  sourceAMap.set(e.ticker, e);
}

// Collect all tickers from both sources
const allTickers = new Set([
  ...sourceAMap.keys(),
  ...Object.keys(SOURCE_B)
]);

const rows = [];
for (const ticker of [...allTickers].sort()) {
  const a = sourceAMap.get(ticker) || null;
  const b = SOURCE_B[ticker] || null;

  const name        = a ? a.name        : ticker;   // fallback to ticker if Source A missing
  const issuer      = a ? a.issuer      : null;
  const cik         = a ? a.cik         : null;
  const series_id   = a ? a.series_id   : null;
  const notes       = a ? (a.notes || null) : null;
  const asset_class = b ? (b.assetClass || null) : null;
  const index_name  = b ? (b.index     !== undefined ? b.index : null) : null;

  // has_nport: 0 if series_id is null OR notes field is present; else 1
  const has_nport = (series_id === null || notes !== null) ? 0 : 1;

  // coverage_status: 'deep' if has_nport=1, else 'directory'
  const coverage_status = has_nport === 1 ? 'deep' : 'directory';

  rows.push({
    ticker, name, issuer, asset_class, index_name,
    cik, series_id, has_nport, coverage_status, notes
  });
}

// ── GENERATE SQL ──────────────────────────────────────────────────────────────
const lines = [
  '-- seed-data.sql',
  '-- Generated by seed-etf-master.js',
  `-- Generated at: ${new Date().toISOString()}`,
  '',
  'BEGIN TRANSACTION;',
  ''
];

for (const r of rows) {
  lines.push(
    `INSERT OR REPLACE INTO etf_master ` +
    `(ticker, name, issuer, asset_class, index_name, cik, series_id, has_nport, net_assets, coverage_status, notes) VALUES (` +
    [
      sqlEsc(r.ticker),
      sqlEsc(r.name),
      sqlEsc(r.issuer),
      sqlEsc(r.asset_class),
      sqlEsc(r.index_name),
      sqlEsc(r.cik),
      sqlEsc(r.series_id),
      r.has_nport,
      'NULL',                       // net_assets — Phase 1
      sqlEsc(r.coverage_status),
      sqlEsc(r.notes)
    ].join(', ') +
    `);`
  );
}

lines.push('');
lines.push('COMMIT;');

const outPath = path.join(__dirname, 'seed-data.sql');
fs.writeFileSync(outPath, lines.join('\n'), 'utf8');

